        <AnimatePresence>
           {isItemFormOpen && (
              <motion.div 
                 initial={{ opacity: 0 }} 
                 animate={{ opacity: 1 }} 
                 exit={{ opacity: 0 }} 
                 className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs"
              >
                 <motion.div 
                    initial={{ scale: 0.95, y: 20 }} 
                    animate={{ scale: 1, y: 0 }} 
                    exit={{ scale: 0.95, y: 20 }} 
                    className={`w-[650px] max-w-[95vw] rounded-2xl overflow-hidden shadow-2xl border flex flex-col transition-all ${isDark ? 'bg-[#0d1117] border-[#30363d]' : 'bg-white border-slate-200'}`}
                 >
                    {/* Form Header */}
                    <div className={`p-5 flex justify-between items-center shrink-0 border-b ${isDark ? 'bg-[#161b22] border-[#30363d] text-white' : 'bg-[#f8f9fa] border-slate-200 text-slate-800'}`}>
                       <div>
                          <h3 className="text-base font-black uppercase italic tracking-tighter flex items-center gap-2">
                             <Pencil className="text-[#10ac84]" size={16}/>
                             {itemMgmtForm.id === null ? 'Create New Item' : 'Modify Item Details'}
                          </h3>
                          <p className="text-[9px] font-black uppercase tracking-[0.2em] text-[#8b949e] mt-0.5">Define item telemetry and validation targets</p>
                       </div>
                       <button onClick={() => setIsItemFormOpen(false)} className={`p-2 rounded-full transition-all ${isDark ? 'hover:bg-white/10 text-[#8b949e] hover:text-white' : 'hover:bg-slate-200 text-slate-500 hover:text-slate-900'}`}>✕</button>
                    </div>

                    {/* Form Body */}
                    <form onSubmit={handleSaveItemMgmt} className="flex flex-col flex-1">

